import XCTest
import KSLCore
import KSLPhysics
@testable import KSLGuidance

final class TAEMReferenceRecoveryTests: XCTestCase {
  func testRejectedRecordedReferenceCannotCommandBallisticDive() throws {
    // Genuine first TAEM state/configuration from the archived 12d39ba run,
    // runs/20261102T040424-mm304-shooting-live-72km. No altered vehicle.
    let c = try JSONDecoder().decode(MissionConfiguration.self, from: Data(Self.configuration.utf8))
    let state = try JSONDecoder().decode(VehicleState.self, from: Data(Self.handoff.utf8))
    let atmosphere = try AtmosphericModelEngine(planet: c.planet)
    let aero = try AerodynamicsEngine(referenceArea: c.vehicle.referenceArea)
    let nep = try XCTUnwrap(NominalEnergyPointSolver(configuration: c,
      atmosphere: atmosphere, aerodynamics: aero).solve(from: state))
    let engine = TAEMGuidanceEngine(configuration: c, atmosphere: atmosphere, aerodynamics: aero)
    let target = engine.update(state, nep: nep, liftGain: 1, dragGain: 1,
      attainableAlphaCeiling: nil, pitchResponseSeconds: nil, rollResponseSeconds: nil)
    XCTAssertEqual(engine.status.descentCheckFailure, "negativeNormalLift")
    XCTAssertEqual(engine.status.referenceTracking, false)
    let efficient = aero.bestGlideAlpha(mach: state.aerodynamics.mach,
      maximumAlpha: c.vehicle.maximumAngleOfAttack, dynamicPressure: state.aerodynamics.dynamicPressure)
    XCTAssertEqual(target.angleOfAttack, efficient, accuracy: 1e-5)
    XCTAssertEqual(target.bank, 0, accuracy: 1e-8)
    XCTAssertEqual(target.desiredFlightPath, state.flightPathAngle, accuracy: 1e-10)
  }

